def apply_txn(ops, state):
    """Apply a transaction's ops atomically to a copy of state.
    Return new state dict, or None if any observation mismatches."""
    st = dict(state)
    for op in ops:
        kind = op[0]
        if kind == 'get':
            key, expect = op[1], op[2]
            cur = st.get(key)
            if cur is None and key not in st:
                if expect is not None:
                    return None
            elif cur != expect:
                return None
        elif kind == 'put':
            key, val = op[1], op[2]
            if val is None:
                st.pop(key, None)
            else:
                st[key] = val
        elif kind == 'del':
            st.pop(op[1], None)
        elif kind == 'cas':
            _, key, old, new, want = op
            cur = st.get(key)
            equal = (cur == old) if not (cur is None and old is None) else True
            # absent key reads as null
            if key not in st:
                equal = (old is None)
            else:
                equal = (cur == old)
            if equal != want:
                return None
            if equal:
                if new is None:
                    st.pop(key, None)
                else:
                    st[key] = new
        elif kind == 'scan':
            low, high, pairs = op[1], op[2], op[3]
            got = [[k, st[k]] for k in sorted(st) if low <= k < high]
            if got != pairs:
                return None
        else:
            return None
    return st


