    ids = [t['id'] for t in txns]
    # predecessors mask: j must precede i if txns[j].end <= txns[i].start
    preds = [0] * n
    for i in range(n):
        for j in range(n):
            if j != i and txns[j]['end'] <= txns[i]['start']:
                preds[i] |= (1 << j)
    full = (1 << n) - 1
    ops = [t['ops'] for t in txns]

    def state_key(st):
        return tuple(sorted(st.items()))

    visited = set()

    def dfs(mask, state):
