import json, sys


def apply_txn(ops, state):
    """Apply a transaction's ops atomically to a copy of state.
    Return the new state dict, or None if any observation mismatches."""
    st = dict(state)
    for op in ops:
        kind = op[0]
        if kind == 'get':
            key, expect = op[1], op[2]
            cur = st[key] if key in st else None  # absent key reads as null
            if cur != expect:
                return None
        elif kind == 'put':
            st[op[1]] = op[2]
        elif kind == 'del':
            st.pop(op[1], None)
        elif kind == 'cas':
            _, key, old, new, want = op
            cur = st[key] if key in st else None  # absent key reads as null
            ok = (cur == old)
            if ok != want:
                return None
            if ok:
                if new is None:
                    st.pop(key, None)
                else:
                    st[key] = new
        elif kind == 'scan':
            low, high, pairs = op[1], op[2], op[3]
            got = [[k, st[k]] for k in sorted(st) if low <= k < high]
            if got != pairs:
                return None
        else:
            return None
    return st


def solve(request):
    txns = request.get('transactions', [])
    initial = dict(request.get('initial', {}) or {})
    final = dict(request.get('final', {}) or {})
    n = len(txns)
    if n == 0:
        return {'order': [] if initial == final else None}

    ids = [t['id'] for t in txns]
    # predecessors mask: bit j set if txns[j] must precede txns[i] (end<=start)
    preds = [0] * n
    for i in range(n):
        for j in range(n):
            if j != i and txns[j]['end'] <= txns[i]['start']:
                preds[i] |= (1 << j)
    full = (1 << n) - 1
    ops = [t['ops'] for t in txns]

    def state_key(st):
        return tuple(sorted(st.items()))

    visited = set()

    def dfs(mask, state):
        if mask == full:
            return [] if state == final else None
        key = (mask, state_key(state))
        if key in visited:
            return None
        for i in range(n):
            bit = 1 << i
            if mask & bit:
                continue
            if preds[i] & ~mask:
                continue
            new = apply_txn(ops[i], state)
            if new is None:
                continue
            sub = dfs(mask | bit, new)
            if sub is not None:
                return [ids[i]] + sub
        visited.add(key)
        return None

    order = dfs(0, initial)
    return {'order': order}


def main():
    out = sys.stdout
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        try:
            req = json.loads(line)
        except ValueError:
            out.write('{"order":null}\n')
            continue
        out.write(json.dumps(solve(req)) + '\n')
    out.flush()


if __name__ == '__main__':
    main()
